update public.reading_logical_items as target
set catalog_search_text = backfill.catalog_search_text
from backfill
where target.logical_item_id = backfill.logical_item_id;

do $assert$
declare
  ctw_count integer;
  rdl_count integer;
  rap_count integer;
  logical_nonempty_count integer;
  rdl_material_count integer;
  rdl_material_nonempty_count integer;
begin
  select count(*) filter (where module = 'ctw'),
         count(*) filter (where module = 'rdl'),
         count(*) filter (where module = 'rap'),
         count(*) filter (
           where module in ('ctw', 'rdl', 'rap')
             and nullif(btrim(catalog_search_text), '') is not null
         )
  into ctw_count, rdl_count, rap_count, logical_nonempty_count
  from public.reading_logical_items
  where module in ('ctw', 'rdl', 'rap');

  if ctw_count <> 214 or rdl_count <> 161 or rap_count <> 109 then
    raise exception 'Unexpected Reading logical item counts: CTW %, RDL %, RAP %',
      ctw_count, rdl_count, rap_count;
  end if;

  if logical_nonempty_count <> 484 then
    raise exception 'Expected 484 non-empty Reading logical catalog rows, found %',
      logical_nonempty_count;
  end if;

  select count(*),
         count(*) filter (where nullif(btrim(catalog_search_text), '') is not null)
  into rdl_material_count, rdl_material_nonempty_count
  from public.reading_materials
  where hitbox_data_path is not null;

  if rdl_material_count <> 161 or rdl_material_nonempty_count <> 161 then
    raise exception 'Expected 161 non-empty RDL material catalog rows, found % of %',
      rdl_material_nonempty_count, rdl_material_count;
  end if;
end
$assert$;

commit;
